{
  "root_causes": [
    {
      "service": "ts-auth-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_request_method, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name='GET' GROUP BY ALL",
          "claim": "Auth's outgoing verification-code GET calls return 405 in abnormal period, 2118 of them, all Error status."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_request_method, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='ts-verification-code-service' AND span_name IN ('PUT /error','GET /api/v1/verifycode/verify/{verifyCode}') GROUP BY ALL",
          "claim": "Verification-code receives 2118 PUT requests that hit /error with 405, while its verify GET handler saw only 26 requests."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) c, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "Auth login endpoint returns HTTP 500 with Error status on 2118 abnormal requests, p95 about 12 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) c, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "User-facing ui-dashboard login returns 500 on 120 requests, median about 3.7 s from retried auth calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name IN ('ts-auth-service','ts-ui-dashboard') AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "Auth login 500 errors propagate to ui-dashboard login, which also returns 500 after repeated retries."
        }
      ]
    }
  ]
}

